export const MEDIA_STORY_COUNT = wvMediaStories.length;

export function getPublicReadyMedia(): MediaStory[] {
  return wvMediaStories.filter((m) => m.reviewStatus === 'public_ready');
}

export function findMediaByValues(
  targetValues: string[],
  limit = 5,
): MediaStory[] {
  const scored = wvMediaStories
    .filter((m) => m.reviewStatus === 'public_ready')
    .map((m) => {
      const matches = m.valuePattern.filter((v) =>
        targetValues.includes(v),
      ).length;
      return { media: m, score: matches };
    })
    .filter((s) => s.score > 0)
    .sort((a, b) => b.score - a.score);
  return scored.slice(0, limit).map((s) => s.media);
}

export function validateMediaStories(): { total: number; publicReady: number; valid: boolean } {
  const publicReady = wvMediaStories.filter((m) => m.reviewStatus === 'public_ready').length;
  return {
    total: wvMediaStories.length,
    publicReady,
    valid: publicReady >= 240,
  };
}
